import { existsSync, readFileSync, renameSync, writeFileSync } from "node:fs";
import os from "node:os";
import path from "node:path";

export type NotifyLevel = "info" | "warning" | "error" | "success";

export type UiApi = {
  notify?: (message: string, level?: NotifyLevel) => void;
  setStatus?: (id: string, status: string | undefined) => void;
  setWidget?: (id: string, widget: unknown) => void;
  confirm?: (title: string, message: string) => Promise<boolean>;
  custom?: <T>(
    factory: (
      tui: { requestRender: (full?: boolean) => void; stop: () => void; start: () => void },
      theme: unknown,
      keybindings: unknown,
      done: (result: T) => void,
    ) => {
      render: (width: number) => string[];
      handleInput?: (data: string) => void;
      invalidate?: () => void;
    },
    options?: { overlay?: boolean; overlayOptions?: unknown; onHandle?: (handle: unknown) => void },
  ) => Promise<T>;
};

export type ExtensionCommandContext = {
  ui: UiApi;
  hasUI?: boolean;
  cwd?: string;
};

export type ExtensionAPI = {
  registerCommand: (
    name: string,
    options: {
      description: string;
      handler: (args: string | undefined, ctx: ExtensionCommandContext) => Promise<void> | void;
    },
  ) => void;
  on?: (
    eventName: string,
    handler: (event: unknown, ctx: ExtensionCommandContext) => Promise<void> | void,
  ) => void;
};

export type WorkspaceSummary = {
  id: string;
  label: string;
  path: string;
  domains?: string[];
};

export type ApiError = Error & { status?: number; body?: string };

export function getBaseUrl(): string {
  return (process.env.RORCA_BASE_URL?.trim() || "http://localhost:3030").replace(/\/$/, "");
}

export function readDefaultToken(): string | undefined {
  const tokenPath = path.join(os.homedir(), ".rorca", "mcp-token");
  if (!existsSync(tokenPath)) {
    return undefined;
  }

  try {
    const token = readFileSync(tokenPath, "utf8").trim();
    return token || undefined;
  } catch {
    return undefined;
  }
}

export function notify(ui: UiApi | undefined, message: string, level: NotifyLevel = "info"): void {
  if (typeof ui?.notify === "function") {
    ui.notify(message, level);
    return;
  }

  const prefix = level === "error" ? "[rorca:error]" : level === "warning" ? "[rorca:warn]" : "[rorca]";
  const text = `${prefix} ${message}`;
  if (level === "error") {
    console.error(text);
  } else if (level === "warning") {
    console.warn(text);
  } else {
    console.log(text);
  }
}

export function buildHeaders(token?: string, extra?: Record<string, string>): Record<string, string> {
  const headers: Record<string, string> = {
    Accept: "application/json",
    ...extra,
  };
  if (token) {
    headers.Authorization = `Bearer ${token}`;
  }
  return headers;
}

export async function apiFetchJson<T>(
  baseUrl: string,
  pathname: string,
  options: { method?: string; body?: unknown; token?: string } = {},
): Promise<T> {
  const response = await fetch(`${baseUrl}${pathname}`, {
    method: options.method ?? (options.body == null ? "GET" : "POST"),
    headers: buildHeaders(options.token, options.body == null ? undefined : { "Content-Type": "application/json" }),
    body: options.body == null ? undefined : JSON.stringify(options.body),
  });

  if (!response.ok) {
    const body = await response.text().catch(() => "");
    const error = new Error(`HTTP ${response.status} ${response.statusText} for ${pathname}`) as ApiError;
    error.status = response.status;
    error.body = body;
    throw error;
  }

  return (await response.json()) as T;
}

export async function apiFetchText(
  baseUrl: string,
  pathname: string,
  options: { method?: string; body?: unknown; token?: string } = {},
): Promise<string> {
  const response = await fetch(`${baseUrl}${pathname}`, {
    method: options.method ?? (options.body == null ? "GET" : "POST"),
    headers: buildHeaders(options.token, options.body == null ? undefined : { "Content-Type": "application/json" }),
    body: options.body == null ? undefined : JSON.stringify(options.body),
  });

  if (!response.ok) {
    const body = await response.text().catch(() => "");
    const error = new Error(`HTTP ${response.status} ${response.statusText} for ${pathname}`) as ApiError;
    error.status = response.status;
    error.body = body;
    throw error;
  }

  return response.text();
}

export async function getWorkspaces(baseUrl: string, token?: string): Promise<WorkspaceSummary[]> {
  const payload = await apiFetchJson<{ items?: WorkspaceSummary[] }>(baseUrl, "/api/workspaces", { token });
  return payload.items ?? [];
}

export async function resolveWorkspace(
  baseUrl: string,
  token?: string,
  preferredWorkspaceId?: string,
  cwdHint?: string,
): Promise<WorkspaceSummary> {
  const envId = preferredWorkspaceId || process.env.RORCA_WORKSPACE_ID?.trim();
  const workspaces = await getWorkspaces(baseUrl, token);
  if (workspaces.length === 0) {
    throw new Error("No workspaces registered in Rorca");
  }

  if (envId) {
    const match = workspaces.find((workspace) => workspace.id === envId);
    if (match) {
      return match;
    }
  }

  const candidateCwds = [cwdHint?.trim(), process.cwd()].filter((value): value is string => Boolean(value));
  for (const cwd of candidateCwds) {
    const cwdMatch = workspaces.find((workspace) => cwd === workspace.path || cwd.startsWith(`${workspace.path}${path.sep}`));
    if (cwdMatch) {
      return cwdMatch;
    }
  }

  return workspaces[0]!;
}

export function truncate(value: string, max: number): string {
  if (max <= 0) {
    return "";
  }
  return value.length <= max ? value : `${value.slice(0, Math.max(0, max - 3))}...`;
}

export function leftTruncate(value: string, max: number): string {
  if (max <= 0) {
    return "";
  }
  return value.length <= max ? value : `...${value.slice(-(max - 3))}`;
}

export function pad(value: string, width: number): string {
  if (width <= 0) {
    return "";
  }
  if (value.length >= width) {
    return value.slice(0, width);
  }
  return value + " ".repeat(width - value.length);
}

export function timeAgo(iso: string | null | undefined): string {
  if (!iso) {
    return "unknown";
  }

  const elapsedMs = Date.now() - new Date(iso).getTime();
  if (!Number.isFinite(elapsedMs)) {
    return "unknown";
  }
  if (elapsedMs < 60_000) {
    return "<1m";
  }
  const minutes = Math.floor(elapsedMs / 60_000);
  if (minutes < 60) {
    return `${minutes}m ago`;
  }
  const hours = Math.floor(minutes / 60);
  if (hours < 24) {
    return `${hours}h ago`;
  }
  const days = Math.floor(hours / 24);
  return `${days}d ago`;
}

export function normalizeKey(chunk: string): string {
  switch (chunk) {
    case "\u0003":
      return "ctrl+c";
    case "\r":
    case "\n":
      return "enter";
    case "\u001b":
      return "escape";
    case "\u001b[A":
      return "up";
    case "\u001b[B":
      return "down";
    case "\u001b[C":
      return "right";
    case "\u001b[D":
      return "left";
    case "\u001b[5~":
      return "pageup";
    case "\u001b[6~":
      return "pagedown";
    case "\u001b[H":
    case "\u001bOH":
      return "home";
    case "\u001b[F":
    case "\u001bOF":
      return "end";
    case "\t":
      return "tab";
    default:
      return chunk;
  }
}

export function readJsonFile<T>(filePath: string, fallback: T): T {
  if (!existsSync(filePath)) {
    return fallback;
  }
  try {
    return JSON.parse(readFileSync(filePath, "utf8")) as T;
  } catch {
    return fallback;
  }
}

export function writeJsonAtomic(filePath: string, value: unknown): void {
  const tmpFilePath = `${filePath}.tmp`;
  writeFileSync(tmpFilePath, JSON.stringify(value, null, 2), "utf8");
  renameSync(tmpFilePath, filePath);
}

export function decodeOutputLines(payload: unknown): string[] {
  if (!payload || typeof payload !== "object") {
    return [];
  }
  const output = (payload as { output?: unknown }).output;
  return Array.isArray(output) ? output.map((line) => String(line)) : [];
}

import {
  type ExtensionAPI,
  type ExtensionCommandContext,
  apiFetchJson,
  normalizeKey,
  notify,
  pad,
  resolveWorkspace,
  timeAgo,
  truncate,
} from "./shared.js";
import { openRunView } from "./run-view.js";
import { openSpecDetail } from "./spec-detail.js";

type KanbanCard = {
  id: string;
  title: string;
  status?: string;
  storyCount?: number;
  model?: string | null;
  createdAt?: string;
  created_at?: string;
  activeRunStatus?: string | null;
  queuePosition?: number | null;
  userStories?: unknown[];
};

type KanbanResponse = {
  columns?: Array<{ id?: string; title?: string; specs?: KanbanCard[]; items?: KanbanCard[] }>;
  items?: KanbanCard[];
};

type BoardColumn = {
  key: string;
  title: string;
  cards: KanbanCard[];
};

type PipelineRunListItem = {
  id: number;
  status?: string;
  spec_path?: string;
};

type PipelineRunListResponse = {
  items?: PipelineRunListItem[];
};

const MAX_VISIBLE_CARDS_PER_COLUMN = 5;

function getCardsFromResponse(payload: KanbanResponse): KanbanCard[] {
  if (Array.isArray(payload.columns)) {
    return payload.columns.flatMap((column) => column.specs ?? column.items ?? []);
  }
  return payload.items ?? [];
}

function normalizeColumnKey(value: string | undefined): string {
  return (value || "draft").trim().toLowerCase().replace(/[^a-z0-9]+/g, "_");
}

function buildFallbackColumns(cards: KanbanCard[]): BoardColumn[] {
  const columns: BoardColumn[] = [
    { key: "draft", title: "DRAFT", cards: [] },
    { key: "in_progress", title: "IN PROGRESS", cards: [] },
    { key: "done", title: "DONE", cards: [] },
  ];

  for (const card of cards) {
    if (card.activeRunStatus === "running" || card.activeRunStatus === "queued") {
      columns[1].cards.push(card);
    } else if (card.status === "passed" || card.status === "done" || card.status === "completed") {
      columns[2].cards.push(card);
    } else {
      columns[0].cards.push(card);
    }
  }

  return columns;
}

function toColumns(payload: KanbanResponse): BoardColumn[] {
  if (Array.isArray(payload.columns) && payload.columns.length > 0) {
    return payload.columns.map((column, index) => ({
      key: normalizeColumnKey(column.id ?? column.title ?? `column_${index + 1}`),
      title: (column.title ?? column.id ?? `Column ${index + 1}`).toUpperCase(),
      cards: column.specs ?? column.items ?? [],
    }));
  }

  return buildFallbackColumns(getCardsFromResponse(payload));
}

function clampIndexes(columns: BoardColumn[], columnIndex: number, rowIndex: number) {
  const safeColumnIndex = Math.max(0, Math.min(columnIndex, columns.length - 1));
  const maxRow = Math.max(0, (columns[safeColumnIndex]?.cards.length ?? 1) - 1);
  return {
    columnIndex: safeColumnIndex,
    rowIndex: Math.max(0, Math.min(rowIndex, maxRow)),
  };
}

function findCardPosition(columns: BoardColumn[], specId: string | null | undefined): { columnIndex: number; rowIndex: number } | null {
  if (!specId) {
    return null;
  }

  for (let nextColumnIndex = 0; nextColumnIndex < columns.length; nextColumnIndex += 1) {
    const nextRowIndex = columns[nextColumnIndex]?.cards.findIndex((card) => card.id === specId) ?? -1;
    if (nextRowIndex >= 0) {
      return { columnIndex: nextColumnIndex, rowIndex: nextRowIndex };
    }
  }

  return null;
}

function cardRunState(card: KanbanCard): string {
  if (card.activeRunStatus === "running") {
    return "running";
  }
  if (card.activeRunStatus === "queued") {
    return `queued#${card.queuePosition ?? "?"}`;
  }
  return card.status || "draft";
}

function extractSpecSlug(specPath: string | undefined): string {
  const fileName = specPath?.split("/").pop() ?? "";
  return fileName.endsWith(".json") ? fileName.slice(0, -5) : fileName;
}

function sortRunCandidates(items: PipelineRunListItem[]): PipelineRunListItem[] {
  const priority = new Map<string, number>([
    ["running", 0],
    ["paused", 1],
    ["queued", 2],
    ["cancelling", 3],
    ["failed", 4],
    ["partial_failure", 5],
    ["done", 6],
    ["passed", 7],
    ["cancelled", 8],
  ]);

  return [...items].sort((left, right) => {
    const leftPriority = priority.get(left.status || "") ?? 99;
    const rightPriority = priority.get(right.status || "") ?? 99;
    if (leftPriority !== rightPriority) {
      return leftPriority - rightPriority;
    }
    return right.id - left.id;
  });
}

function canStartRun(card: KanbanCard | undefined): boolean {
  if (!card) {
    return false;
  }
  return card.activeRunStatus !== "running" && card.activeRunStatus !== "queued";
}

function renderColumns(columns: BoardColumn[], columnIndex: number, rowIndex: number, width: number): string[] {
  const visibleColumns = columns.length > 0 ? columns : [{ key: "draft", title: "SPECS", cards: [] }];
  const totalWidth = Math.max(90, width);
  const separatorWidth = Math.max(0, (visibleColumns.length - 1) * 3);
  const columnWidth = Math.max(24, Math.floor((totalWidth - separatorWidth) / visibleColumns.length));
  const heights = visibleColumns.map((column, idx) => {
    const visibleCount = idx === columnIndex
      ? Math.min(column.cards.length, MAX_VISIBLE_CARDS_PER_COLUMN)
      : Math.min(column.cards.length, Math.max(3, MAX_VISIBLE_CARDS_PER_COLUMN - 1));
    const overflowRows = column.cards.length > visibleCount ? 1 : 0;
    return Math.max(4, 1 + Math.max(1, visibleCount * 2) + overflowRows);
  });
  const maxHeight = Math.max(...heights);

  const rendered = visibleColumns.map((column, idx) => {
    const lines: string[] = [];
    const selectedRow = idx === columnIndex ? rowIndex : 0;
    const visibleCount = idx === columnIndex
      ? Math.min(column.cards.length, MAX_VISIBLE_CARDS_PER_COLUMN)
      : Math.min(column.cards.length, Math.max(3, MAX_VISIBLE_CARDS_PER_COLUMN - 1));
    const start = idx === columnIndex
      ? Math.max(0, Math.min(selectedRow - Math.floor(visibleCount / 2), Math.max(0, column.cards.length - visibleCount)))
      : 0;
    const end = start + visibleCount;
    const hiddenAbove = start;
    const hiddenBelow = Math.max(0, column.cards.length - end);

    lines.push(pad(`[${column.title} • ${column.cards.length}]`, columnWidth));

    if (column.cards.length === 0) {
      lines.push(pad("No specs in this column.", columnWidth));
    } else {
      if (hiddenAbove > 0) {
        lines.push(pad(truncate(`… ${hiddenAbove} above`, columnWidth), columnWidth));
      }

      column.cards.slice(start, end).forEach((card, visibleIdx) => {
        const cardIdx = start + visibleIdx;
        const focused = idx === columnIndex && cardIdx === rowIndex;
        const marker = focused ? "> " : "  ";
        const storyCount = card.storyCount ?? card.userStories?.length ?? 0;
        const title = truncate(card.title || card.id, Math.max(10, columnWidth - 2));
        const meta = `${storyCount} stories • ${cardRunState(card)} • ${timeAgo(card.createdAt ?? card.created_at)}`;
        lines.push(pad(truncate(`${marker}${title}`, columnWidth), columnWidth));
        lines.push(pad(truncate(`   ${meta}`, columnWidth), columnWidth));
      });

      if (hiddenBelow > 0) {
        lines.push(pad(truncate(`… ${hiddenBelow} more`, columnWidth), columnWidth));
      }
    }

    while (lines.length < maxHeight) {
      lines.push(" ".repeat(columnWidth));
    }

    return lines;
  });

  const out: string[] = [];
  for (let row = 0; row < maxHeight; row += 1) {
    out.push(rendered.map((column) => column[row] ?? " ".repeat(columnWidth)).join(" │ "));
  }
  return out;
}

export async function openSpecBoard(
  ctx: ExtensionCommandContext,
  _pi: ExtensionAPI,
  baseUrl: string,
  token?: string,
): Promise<void> {
  const workspace = await resolveWorkspace(baseUrl, token, process.env.RORCA_WORKSPACE_ID?.trim() || undefined, ctx.cwd);

  if (!ctx.ui.custom) {
    notify(ctx.ui, "Pi custom UI is unavailable in this session. Use /rorca-tui as fallback.", "warning");
    return;
  }

  let reopenBoard = true;
  let highlightedSpecId: string | null = null;
  let selectedRunId: number | null = null;

  while (reopenBoard) {
    let selectedSpecId: string | null = null;
    selectedRunId = null;
    reopenBoard = false;

    await ctx.ui.custom<void>((tui, _theme, _keybindings, done) => {
      let columns: BoardColumn[] = toColumns({ items: [] });
      let columnIndex = 0;
      let rowIndex = 0;
      let busy = true;
      let statusLine = "Loading specs…";
      let mounted = true;
      let refreshTimer: NodeJS.Timeout | undefined;

    const currentCard = () => columns[columnIndex]?.cards[rowIndex];

    const requestRender = () => {
      if (mounted) {
        tui.requestRender();
      }
    };

      const refresh = async () => {
        const payload = await apiFetchJson<KanbanResponse>(
          baseUrl,
          `/api/specs/kanban?workspaceId=${encodeURIComponent(workspace.id)}`,
          { token },
        );
        columns = toColumns(payload);
        const preferredPosition = findCardPosition(columns, highlightedSpecId);
        const clamped = preferredPosition ?? clampIndexes(columns, columnIndex, rowIndex);
        columnIndex = clamped.columnIndex;
        rowIndex = clamped.rowIndex;
        statusLine = `Workspace ${workspace.label} • ${columns.reduce((sum, column) => sum + column.cards.length, 0)} specs`;
      };

      const resolveLatestRunId = async (specId: string): Promise<number | null> => {
        const payload = await apiFetchJson<PipelineRunListResponse>(
          baseUrl,
          `/api/pipeline/runs?workspaceId=${encodeURIComponent(workspace.id)}&limit=100`,
          { token },
        );
        const matches = (payload.items ?? []).filter((item) => extractSpecSlug(item.spec_path) === specId);
        return sortRunCandidates(matches)[0]?.id ?? null;
      };

      const runAction = (action: () => Promise<void>) => {
        if (busy) {
          return;
        }
        busy = true;
        statusLine = "Working…";
        requestRender();

        void (async () => {
          try {
            await action();
            await refresh();
          } catch (error) {
            const message = error instanceof Error ? error.message : String(error);
            statusLine = `Error: ${message}`;
            notify(ctx.ui, message, "error");
          } finally {
            busy = false;
            requestRender();
          }
        })();
      };

      const startRefreshTimer = () => {
        if (refreshTimer) {
          clearInterval(refreshTimer);
        }
        refreshTimer = setInterval(() => {
          void refresh().then(requestRender).catch((error) => {
            const message = error instanceof Error ? error.message : String(error);
            statusLine = `Refresh failed: ${message}`;
            requestRender();
          });
        }, 30_000);
      };

      void (async () => {
        try {
          await refresh();
        } catch (error) {
          const message = error instanceof Error ? error.message : String(error);
          statusLine = `Failed to load board: ${message}`;
          notify(ctx.ui, message, "error");
        } finally {
          busy = false;
          startRefreshTimer();
          requestRender();
        }
      })();

      return {
      handleInput(data: string) {
        const key = normalizeKey(data);

        if (key === "q" || key === "escape" || key === "ctrl+c") {
          mounted = false;
          if (refreshTimer) {
            clearInterval(refreshTimer);
          }
          done();
          return;
        }

        if (busy) {
          return;
        }

        if (key === "down" || key === "j") {
          rowIndex = Math.min(rowIndex + 1, Math.max(0, columns[columnIndex]?.cards.length - 1));
          requestRender();
          return;
        }

        if (key === "up" || key === "k") {
          rowIndex = Math.max(0, rowIndex - 1);
          requestRender();
          return;
        }

        if (key === "home") {
          rowIndex = 0;
          requestRender();
          return;
        }

        if (key === "end") {
          rowIndex = Math.max(0, columns[columnIndex]?.cards.length - 1);
          requestRender();
          return;
        }

        if (key === "left" || key === "h") {
          const clamped = clampIndexes(columns, (columnIndex + columns.length - 1) % columns.length, rowIndex);
          columnIndex = clamped.columnIndex;
          rowIndex = clamped.rowIndex;
          requestRender();
          return;
        }

        if (key === "right" || key === "l" || key === "tab") {
          const clamped = clampIndexes(columns, (columnIndex + 1) % columns.length, rowIndex);
          columnIndex = clamped.columnIndex;
          rowIndex = clamped.rowIndex;
          requestRender();
          return;
        }

        if (key === "r") {
          runAction(async () => {
            startRefreshTimer();
            await refresh();
            statusLine = `Workspace ${workspace.label} • refreshed`;
          });
          return;
        }

        if (key === "s") {
          const card = currentCard();
          if (!canStartRun(card)) {
            statusLine = card ? `${card.title} already has an active run.` : "No spec selected.";
            requestRender();
            return;
          }
          runAction(async () => {
            const payload = await apiFetchJson<{ queued?: boolean; runId?: number; queuePosition?: number }>(
              baseUrl,
              `/api/pipeline/queue`,
              {
                method: "POST",
                token,
                body: { workspaceId: workspace.id, specId: card.id },
              },
            );
            if (payload.queued) {
              statusLine = `Queued ${card.title} at position ${payload.queuePosition ?? "?"}`;
              notify(ctx.ui, statusLine, "info");
            } else {
              statusLine = `Started run ${payload.runId ?? ""} for ${card.title}`.trim();
              notify(ctx.ui, statusLine, "success");
            }
          });
          return;
        }

        if (key === "o") {
          const card = currentCard();
          if (!card) {
            statusLine = "No spec selected.";
            requestRender();
            return;
          }
          runAction(async () => {
            const runId = await resolveLatestRunId(card.id);
            if (!runId) {
              statusLine = `No pipeline run found yet for ${card.title}`;
              return;
            }
            highlightedSpecId = card.id;
            selectedRunId = runId;
            mounted = false;
            if (refreshTimer) {
              clearInterval(refreshTimer);
            }
            done();
          });
          return;
        }

        if (key === "a") {
          const card = currentCard();
          if (!card) {
            return;
          }
          runAction(async () => {
            await apiFetchJson(baseUrl, `/api/specs/${encodeURIComponent(card.id)}/approve`, {
              method: "POST",
              token,
              body: { workspaceId: workspace.id },
            });
            statusLine = `Approved ${card.title}`;
            notify(ctx.ui, `Approved ${card.title}`, "success");
          });
          return;
        }

        if (key === "x") {
          const card = currentCard();
          if (!card) {
            return;
          }
          runAction(async () => {
            const ok = (await ctx.ui.confirm?.("Reject spec", `Reject ${card.title}?`)) ?? false;
            if (!ok) {
              statusLine = `Reject cancelled for ${card.title}`;
              return;
            }
            await apiFetchJson(baseUrl, `/api/specs/${encodeURIComponent(card.id)}/reject`, {
              method: "POST",
              token,
              body: { workspaceId: workspace.id, reason: "Rejected from Pi board" },
            });
            statusLine = `Rejected ${card.title}`;
            notify(ctx.ui, `Rejected ${card.title}`, "warning");
          });
          return;
        }

        if (key === "enter") {
          const card = currentCard();
          if (card) {
            highlightedSpecId = card.id;
            selectedSpecId = card.id;
            mounted = false;
            if (refreshTimer) {
              clearInterval(refreshTimer);
            }
            done();
          }
        }
      },

      render(width: number): string[] {
        const lines: string[] = [];
        const card = currentCard();
        const storyCount = card ? card.storyCount ?? card.userStories?.length ?? 0 : 0;
        lines.push(`Rorca Spec Board — ${workspace.label}`);
        lines.push("");
        lines.push(...renderColumns(columns, columnIndex, rowIndex, width));
        lines.push("");
        lines.push(truncate(card ? `Selected: ${card.title || card.id} • ${storyCount} stories • ${cardRunState(card)}` : "Selected: none", Math.max(20, width)));
        lines.push(truncate(statusLine, Math.max(20, width)));
        lines.push(truncate("j/k or ↑/↓ move • Home/End jump • h/l or ←/→ change column • enter detail • s start/queue run • o open latest run • a approve • x reject • r refresh • q quit", Math.max(20, width)));
        return lines;
      },

        invalidate() {
          // Stateless renderer
        },
      };
    });

    if (selectedRunId != null) {
      reopenBoard = true;
      await openRunView(ctx, _pi, selectedRunId, baseUrl, token);
      continue;
    }

    if (selectedSpecId) {
      reopenBoard = true;
      await openSpecDetail(ctx, _pi, selectedSpecId, baseUrl, token, workspace.id);
    }
  }
}

import { openRunView } from "./run-view.js";
import {
  type ExtensionAPI,
  type ExtensionCommandContext,
  apiFetchJson,
  normalizeKey,
  notify,
  timeAgo,
  truncate,
} from "./shared.js";

type SpecStory = {
  id?: string;
  title?: string;
  story?: string;
  description?: string;
  status?: string;
  completed?: boolean;
  excluded?: boolean;
  passes?: boolean;
  complexity?: number;
  priority?: number;
  timeoutMinutes?: number;
  dependsOn?: string[];
  dependencies?: string[];
  acceptanceCriteria?: string[];
  acceptance_criteria?: string[];
  tasks?: string[];
};

type SpecDetailPayload = {
  id?: string;
  specName?: string;
  title?: string;
  brief?: string;
  model?: string | null;
  createdAt?: string;
  created_at?: string;
  _status?: string;
  readinessPercent?: number;
  tags?: string[];
  userStories?: SpecStory[];
  stories?: SpecStory[];
};

type PipelineRunListItem = {
  id: number;
  status?: string;
  spec_path?: string;
};

type PipelineRunListResponse = {
  items?: PipelineRunListItem[];
};

const MAX_VISIBLE_STORIES = 9;
const MAX_VISIBLE_DETAIL_LINES = 18;

function storyTitle(story: SpecStory, index: number): string {
  return story.title || story.story || story.description || `Story ${index + 1}`;
}

function storyCriteria(story: SpecStory): string[] {
  const criteria = story.acceptanceCriteria ?? story.acceptance_criteria ?? [];
  return Array.isArray(criteria) ? criteria.map(String) : [];
}

function storyTasks(story: SpecStory): string[] {
  return Array.isArray(story.tasks) ? story.tasks.map(String) : [];
}

function storyDependencies(story: SpecStory): string[] {
  const dependencies = story.dependsOn ?? story.dependencies ?? [];
  return Array.isArray(dependencies) ? dependencies.map(String) : [];
}

function specStories(spec: SpecDetailPayload): SpecStory[] {
  return spec.userStories ?? spec.stories ?? [];
}

function storyStatus(story: SpecStory): string {
  if (story.status) {
    return story.status;
  }
  return story.completed ? "done" : "pending";
}

function extractSpecSlug(specPath: string | undefined): string {
  const fileName = specPath?.split("/").pop() ?? "";
  return fileName.endsWith(".json") ? fileName.slice(0, -5) : fileName;
}

function sortRunCandidates(items: PipelineRunListItem[]): PipelineRunListItem[] {
  const priority = new Map<string, number>([
    ["running", 0],
    ["paused", 1],
    ["queued", 2],
    ["cancelling", 3],
    ["failed", 4],
    ["partial_failure", 5],
    ["done", 6],
    ["passed", 7],
    ["cancelled", 8],
  ]);

  return [...items].sort((left, right) => {
    const leftPriority = priority.get(left.status || "") ?? 99;
    const rightPriority = priority.get(right.status || "") ?? 99;
    if (leftPriority !== rightPriority) {
      return leftPriority - rightPriority;
    }
    return right.id - left.id;
  });
}

function renderWrapped(text: string, width: number): string[] {
  const safeWidth = Math.max(20, width);
  const words = text.split(/\s+/).filter(Boolean);
  if (words.length === 0) {
    return [""];
  }

  const lines: string[] = [];
  let current = "";
  for (const word of words) {
    const next = current ? `${current} ${word}` : word;
    if (next.length > safeWidth && current) {
      lines.push(current);
      current = word;
    } else {
      current = next;
    }
  }
  if (current) {
    lines.push(current);
  }
  return lines;
}

function visibleStoryWindow(stories: SpecStory[], selectedIndex: number): { start: number; end: number } {
  if (stories.length <= MAX_VISIBLE_STORIES) {
    return { start: 0, end: stories.length };
  }

  const halfWindow = Math.floor(MAX_VISIBLE_STORIES / 2);
  const start = Math.max(0, Math.min(selectedIndex - halfWindow, stories.length - MAX_VISIBLE_STORIES));
  return { start, end: start + MAX_VISIBLE_STORIES };
}

export async function openSpecDetail(
  ctx: ExtensionCommandContext,
  _pi: ExtensionAPI,
  specId: string,
  baseUrl: string,
  token?: string,
  workspaceId?: string,
): Promise<void> {
  if (!ctx.ui.custom) {
    notify(ctx.ui, `Pi custom UI is unavailable for spec ${specId}. Use /rorca-tui as fallback.`, "warning");
    return;
  }

  let openRunId: number | null = null;

  await ctx.ui.custom<void>((tui, _theme, _keybindings, done) => {
    let spec: SpecDetailPayload | null = null;
    let latestRun: PipelineRunListItem | null = null;
    let selectedIndex = 0;
    let scrollOffset = 0;
    let busy = true;
    let mounted = true;
    let refreshTimer: NodeJS.Timeout | undefined;
    let statusLine = `Loading spec ${specId}…`;

    const requestRender = () => {
      if (mounted) {
        tui.requestRender();
      }
    };

    const refresh = async () => {
      if (!workspaceId) {
        throw new Error("No workspace selected for spec detail");
      }
      const [nextSpec, runPayload] = await Promise.all([
        apiFetchJson<SpecDetailPayload>(
          baseUrl,
          `/api/specs/${encodeURIComponent(specId)}?workspaceId=${encodeURIComponent(workspaceId)}`,
          { token },
        ),
        apiFetchJson<PipelineRunListResponse>(
          baseUrl,
          `/api/pipeline/runs?workspaceId=${encodeURIComponent(workspaceId)}&limit=100`,
          { token },
        ),
      ]);
      spec = nextSpec;
      latestRun = sortRunCandidates((runPayload.items ?? []).filter((item) => extractSpecSlug(item.spec_path) === specId))[0] ?? null;
      const stories = specStories(spec);
      selectedIndex = Math.max(0, Math.min(selectedIndex, Math.max(0, stories.length - 1)));
      statusLine = `${spec.title || spec.specName || specId} • ${stories.length} stories • ${spec._status || "unknown"}`;
    };

    const runAction = (action: () => Promise<void>) => {
      if (busy) {
        return;
      }
      busy = true;
      statusLine = "Working…";
      requestRender();

      void (async () => {
        try {
          await action();
          await refresh();
        } catch (error) {
          const message = error instanceof Error ? error.message : String(error);
          statusLine = `Error: ${message}`;
          notify(ctx.ui, message, "error");
        } finally {
          busy = false;
          requestRender();
        }
      })();
    };

    const startRefreshTimer = () => {
      if (refreshTimer) {
        clearInterval(refreshTimer);
      }
      refreshTimer = setInterval(() => {
        void refresh().then(requestRender).catch((error) => {
          const message = error instanceof Error ? error.message : String(error);
          statusLine = `Refresh failed: ${message}`;
          requestRender();
        });
      }, 30_000);
    };

    void (async () => {
      try {
        await refresh();
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        statusLine = `Failed to load spec: ${message}`;
        notify(ctx.ui, message, "error");
      } finally {
        busy = false;
        startRefreshTimer();
        requestRender();
      }
    })();

    return {
      handleInput(data: string) {
        const key = normalizeKey(data);
        const stories = spec ? specStories(spec) : [];

        if (key === "q" || key === "escape" || key === "ctrl+c") {
          mounted = false;
          if (refreshTimer) {
            clearInterval(refreshTimer);
          }
          done();
          return;
        }

        if (busy) {
          return;
        }

        if (key === "down" || key === "j") {
          const nextIndex = Math.min(selectedIndex + 1, Math.max(0, stories.length - 1));
          if (nextIndex !== selectedIndex) {
            selectedIndex = nextIndex;
            scrollOffset = 0;
          }
          requestRender();
          return;
        }

        if (key === "up" || key === "k") {
          const nextIndex = Math.max(0, selectedIndex - 1);
          if (nextIndex !== selectedIndex) {
            selectedIndex = nextIndex;
            scrollOffset = 0;
          }
          requestRender();
          return;
        }

        if (key === "home") {
          selectedIndex = 0;
          scrollOffset = 0;
          requestRender();
          return;
        }

        if (key === "end") {
          selectedIndex = Math.max(0, stories.length - 1);
          scrollOffset = 0;
          requestRender();
          return;
        }

        if (key === "pagedown") {
          const nextIndex = Math.min(selectedIndex + 5, Math.max(0, stories.length - 1));
          if (nextIndex !== selectedIndex) {
            selectedIndex = nextIndex;
            scrollOffset = 0;
          }
          requestRender();
          return;
        }

        if (key === "pageup") {
          const nextIndex = Math.max(0, selectedIndex - 5);
          if (nextIndex !== selectedIndex) {
            selectedIndex = nextIndex;
            scrollOffset = 0;
          }
          requestRender();
          return;
        }

        if (key === "[") {
          scrollOffset = Math.max(0, scrollOffset - 1);
          requestRender();
          return;
        }

        if (key === "]") {
          scrollOffset += 1;
          requestRender();
          return;
        }

        if (key === "r") {
          runAction(async () => {
            await refresh();
            statusLine = `Refreshed ${spec?.title || spec?.specName || specId}`;
          });
          return;
        }

        if (key === "a") {
          runAction(async () => {
            await apiFetchJson(baseUrl, `/api/specs/${encodeURIComponent(specId)}/approve`, {
              method: "POST",
              token,
              body: { workspaceId },
            });
            statusLine = `Approved ${spec?.title || spec?.specName || specId}`;
            notify(ctx.ui, `Approved ${spec?.title || spec?.specName || specId}`, "success");
          });
          return;
        }

        if (key === "x") {
          runAction(async () => {
            const ok = (await ctx.ui.confirm?.("Reject spec", `Reject ${spec?.title || spec?.specName || specId}?`)) ?? false;
            if (!ok) {
              statusLine = `Reject cancelled for ${spec?.title || spec?.specName || specId}`;
              return;
            }
            await apiFetchJson(baseUrl, `/api/specs/${encodeURIComponent(specId)}/reject`, {
              method: "POST",
              token,
              body: { workspaceId, reason: "Rejected from Pi detail" },
            });
            statusLine = `Rejected ${spec?.title || spec?.specName || specId}`;
            notify(ctx.ui, `Rejected ${spec?.title || spec?.specName || specId}`, "warning");
          });
          return;
        }

        if (key === "s") {
          runAction(async () => {
            const payload = await apiFetchJson<{ queued?: boolean; runId?: number; queuePosition?: number }>(
              baseUrl,
              `/api/pipeline/queue`,
              {
                method: "POST",
                token,
                body: { workspaceId, specId },
              },
            );
            if (payload.queued) {
              statusLine = `Queued run for ${spec?.title || spec?.specName || specId} at position ${payload.queuePosition ?? "?"}`;
              notify(ctx.ui, statusLine, "info");
            } else {
              statusLine = `Started run ${payload.runId ?? ""} for ${spec?.title || spec?.specName || specId}`.trim();
              notify(ctx.ui, statusLine, "success");
              if (payload.runId) {
                openRunId = payload.runId;
                mounted = false;
                if (refreshTimer) {
                  clearInterval(refreshTimer);
                }
                done();
              }
            }
          });
          return;
        }

        if (key === "o") {
          if (!latestRun?.id) {
            statusLine = `No pipeline run found yet for ${spec?.title || spec?.specName || specId}`;
            requestRender();
            return;
          }
          openRunId = latestRun.id;
          mounted = false;
          if (refreshTimer) {
            clearInterval(refreshTimer);
          }
          done();
        }
      },

      render(width: number): string[] {
        const lines: string[] = [];
        const safeWidth = Math.max(60, width);
        const leftWidth = Math.max(24, Math.floor(safeWidth * 0.34));
        const rightWidth = Math.max(28, safeWidth - leftWidth - 3);

        lines.push(`Rorca Spec Detail — ${spec?.title || spec?.specName || specId}`);
        lines.push("");

        if (!spec) {
          lines.push(truncate(statusLine, safeWidth));
          lines.push(truncate("q quit", safeWidth));
          return lines;
        }

        const stories = specStories(spec);
        const selectedStory = stories[selectedIndex];
        const criteria = selectedStory ? storyCriteria(selectedStory) : [];
        const tasks = selectedStory ? storyTasks(selectedStory) : [];
        const dependencies = selectedStory ? storyDependencies(selectedStory) : [];
        const summaryLines = [
          `Status: ${spec._status || "unknown"}`,
          `Readiness: ${spec.readinessPercent ?? 0}%`,
          `Stories: ${stories.length}`,
          `Model: ${spec.model || "auto"}`,
          `Created: ${timeAgo(spec.createdAt ?? spec.created_at)}`,
          `Run: ${latestRun ? `#${latestRun.id} ${latestRun.status || "unknown"}` : "none"}`,
          `Tags: ${(spec.tags ?? []).join(", ") || "none"}`,
        ];
        const storyWindow = visibleStoryWindow(stories, selectedIndex);
        const storyList = stories.length
          ? [
              ...(storyWindow.start > 0 ? [truncate(`… ${storyWindow.start} earlier stories`, leftWidth)] : []),
              ...stories.slice(storyWindow.start, storyWindow.end).map((story, visibleIndex) => {
                const index = storyWindow.start + visibleIndex;
                const marker = index === selectedIndex ? ">" : " ";
                const storyId = story.id ? `${story.id} · ` : "";
                const excluded = story.excluded ? " · excluded" : "";
                return truncate(`${marker} ${storyId}${storyTitle(story, index)} [${storyStatus(story)}${excluded}]`, leftWidth);
              }),
              ...(storyWindow.end < stories.length ? [truncate(`… ${stories.length - storyWindow.end} more stories`, leftWidth)] : []),
            ]
          : ["No stories in this spec."];

        const detailLines: string[] = [];
        detailLines.push("Brief:");
        detailLines.push(...renderWrapped(spec.brief || "No brief", Math.max(20, rightWidth - 2)).map((line) => `  ${truncate(line, rightWidth - 2)}`));
        detailLines.push("");
        if (selectedStory) {
          detailLines.push(`Story ${selectedIndex + 1}: ${truncate(storyTitle(selectedStory, selectedIndex), rightWidth - 9)}`);
          detailLines.push(`ID: ${selectedStory.id || `story-${selectedIndex + 1}`}`);
          detailLines.push(`Status: ${storyStatus(selectedStory)}${selectedStory.excluded ? " · excluded" : ""}${selectedStory.passes === true ? " · passes" : ""}`);
          detailLines.push(`Depends on: ${dependencies.join(", ") || "none"}`);
          detailLines.push(`Complexity: ${selectedStory.complexity ?? "n/a"} • Priority: ${selectedStory.priority ?? "n/a"} • Timeout: ${selectedStory.timeoutMinutes ?? "default"}m`);
          const narrative = selectedStory.story || selectedStory.description;
          if (narrative) {
            detailLines.push("Narrative:");
            detailLines.push(...renderWrapped(narrative, rightWidth).map((line) => `  ${truncate(line, rightWidth - 2)}`));
          }
          detailLines.push("Acceptance:");
          if (criteria.length === 0) {
            detailLines.push("  No acceptance criteria");
          } else {
            for (const item of criteria) {
              detailLines.push(...renderWrapped(`• ${item}`, rightWidth).map((line) => truncate(line, rightWidth)));
            }
          }
          detailLines.push("");
          detailLines.push("Tasks:");
          if (tasks.length === 0) {
            detailLines.push("  No implementation tasks");
          } else {
            for (const task of tasks) {
              detailLines.push(...renderWrapped(`• ${task}`, rightWidth).map((line) => truncate(line, rightWidth)));
            }
          }
        } else {
          detailLines.push("Select a story to inspect.");
        }

        const leftPaneLines = [...summaryLines, "", "Stories:", ...storyList];
        const paneHeight = Math.max(leftPaneLines.length, Math.min(MAX_VISIBLE_DETAIL_LINES, Math.max(8, detailLines.length)));
        const maxScrollOffset = Math.max(0, detailLines.length - paneHeight);
        const clampedOffset = Math.max(0, Math.min(scrollOffset, maxScrollOffset));
        if (clampedOffset !== scrollOffset) {
          scrollOffset = clampedOffset;
        }
        const visibleDetails = detailLines.slice(scrollOffset, scrollOffset + paneHeight);

        for (let row = 0; row < paneHeight; row += 1) {
          const left = leftPaneLines[row] || "";
          const right = visibleDetails[row] || "";
          lines.push(`${truncate(left, leftWidth).padEnd(leftWidth)} │ ${truncate(right, rightWidth)}`);
        }

        lines.push("");
        if (maxScrollOffset > 0) {
          lines.push(truncate(`Detail scroll ${scrollOffset + 1}-${Math.min(detailLines.length, scrollOffset + paneHeight)} of ${detailLines.length}`, safeWidth));
        }
        lines.push(truncate(statusLine, safeWidth));
        lines.push(truncate("j/k move stories • Home/End jump • PgUp/PgDn step • s start run and open if immediate • o open latest run • a approve • x reject • r refresh • [/] scroll detail • q quit", safeWidth));
        return lines;
      },

      invalidate() {
        // Stateless renderer
      },
    };
  });

  if (openRunId != null) {
    await openRunView(ctx, _pi, openRunId, baseUrl, token);
  }
}

import {
  type ExtensionAPI,
  type ExtensionCommandContext,
  apiFetchJson,
  normalizeKey,
  notify,
  pad,
  timeAgo,
  truncate,
} from "./shared.js";

type MemoryEntry = {
  id: string | number;
  category?: string;
  content?: string;
  confidence?: string;
  pinned?: boolean;
  sourceType?: string;
  sourceRunId?: number | null;
  createdAt?: string;
};

type MemoryListResponse = {
  items?: MemoryEntry[];
  total?: number;
  pinned?: number;
  recentRunIds?: number[];
  categories?: string[];
  page?: number;
  pageSize?: number;
};

function memoryTimestamp(memory: MemoryEntry): string | null {
  return memory.createdAt ?? null;
}

function memoryPreview(memory: MemoryEntry): string {
  return (memory.content || "No content recorded.").replace(/\s+/g, " ").trim();
}

function memoryTitle(memory: MemoryEntry, index: number): string {
  const prefix = memory.category || "Memory";
  const preview = memoryPreview(memory);
  const snippet = preview ? preview.slice(0, 42) : `${prefix} ${index + 1}`;
  return `${prefix} #${memory.id} • ${snippet}`;
}

function wrapText(value: string, width: number, maxLines: number): string[] {
  const safeWidth = Math.max(12, width);
  const words = value.split(/\s+/).filter(Boolean);
  if (words.length === 0) {
    return [pad(" ", safeWidth)];
  }

  const lines: string[] = [];
  let line = "";
  for (const word of words) {
    const candidate = line ? `${line} ${word}` : word;
    if (candidate.length > safeWidth) {
      lines.push(pad(truncate(line || word, safeWidth), safeWidth));
      line = line ? word : "";
      if (!line && word.length > safeWidth) {
        line = word.slice(safeWidth);
      }
    } else {
      line = candidate;
    }
    if (lines.length >= maxLines) break;
  }
  if (lines.length < maxLines && line) {
    lines.push(pad(truncate(line, safeWidth), safeWidth));
  }
  return lines.slice(0, maxLines);
}

function renderMemoryBrowser(
  memories: MemoryEntry[],
  selectedIndex: number,
  width: number,
  statusLine: string,
  page: number,
  pageSize: number,
  total: number,
  pinnedCount: number,
): string[] {
  const totalWidth = Math.max(88, width);
  const listWidth = Math.max(30, Math.floor(totalWidth * 0.4));
  const detailWidth = Math.max(46, totalWidth - listWidth - 3);
  const selected = memories[selectedIndex];
  const totalPages = Math.max(1, Math.ceil(Math.max(total, 0) / Math.max(pageSize, 1)));
  const visibleRows = 12;
  const start = Math.max(0, Math.min(selectedIndex - Math.floor(visibleRows / 2), Math.max(0, memories.length - visibleRows)));
  const end = start + visibleRows;

  const leftLines: string[] = [pad(`[MEMORIES • page ${page}/${totalPages} • ${total} total]`, listWidth)];
  leftLines.push(pad(truncate(`Pinned ${pinnedCount} • showing ${memories.length}`, listWidth), listWidth));
  if (memories.length === 0) {
    leftLines.push(pad("No memories found on this page.", listWidth));
  } else {
    if (start > 0) {
      leftLines.push(pad(truncate(`… ${start} above`, listWidth), listWidth));
    }
    memories.slice(start, end).forEach((memory, idx) => {
      const actualIndex = start + idx;
      const marker = actualIndex === selectedIndex ? "> " : "  ";
      const pin = memory.pinned ? "★" : " ";
      const meta = `${memory.confidence || "unknown"} • ${memory.sourceType || "unknown"} • ${timeAgo(memoryTimestamp(memory))}`;
      leftLines.push(pad(truncate(`${marker}${pin} ${memoryTitle(memory, actualIndex)}`, listWidth), listWidth));
      leftLines.push(pad(truncate(`   ${meta}`, listWidth), listWidth));
    });
    if (end < memories.length) {
      leftLines.push(pad(truncate(`… ${memories.length - end} more`, listWidth), listWidth));
    }
  }

  const rightLines: string[] = [pad("[DETAIL]", detailWidth)];
  if (!selected) {
    rightLines.push(pad("Select a memory to inspect.", detailWidth));
  } else {
    rightLines.push(pad(truncate(`Id: ${selected.id}`, detailWidth), detailWidth));
    rightLines.push(pad(truncate(`Category: ${selected.category || "unknown"}`, detailWidth), detailWidth));
    rightLines.push(pad(truncate(`Confidence: ${selected.confidence || "unknown"} • ${selected.pinned ? "pinned" : "unpinned"}`, detailWidth), detailWidth));
    rightLines.push(pad(truncate(`Source: ${selected.sourceType || "unknown"} • run ${selected.sourceRunId ?? "n/a"}`, detailWidth), detailWidth));
    rightLines.push(pad(truncate(`Created: ${timeAgo(memoryTimestamp(selected))}`, detailWidth), detailWidth));
    rightLines.push(" ".repeat(detailWidth));
    rightLines.push(...wrapText(memoryPreview(selected), detailWidth, 16));
  }

  const height = Math.max(leftLines.length, rightLines.length);
  while (leftLines.length < height) leftLines.push(" ".repeat(listWidth));
  while (rightLines.length < height) rightLines.push(" ".repeat(detailWidth));

  const lines: string[] = [truncate(statusLine, totalWidth)];
  for (let i = 0; i < height; i += 1) {
    lines.push(`${leftLines[i]} │ ${rightLines[i]}`);
  }
  lines.push(" ");
  lines.push(truncate("↑/↓ move • ←/→ page • r refresh • q/esc close", totalWidth));
  return lines;
}

export async function openMemoryBrowser(
  ctx: ExtensionCommandContext,
  _pi: ExtensionAPI,
  workspaceId: string,
  baseUrl: string,
  token?: string,
): Promise<void> {
  if (!ctx.ui.custom) {
    notify(ctx.ui, "Pi custom UI is unavailable in this session. Use /rorca-tui as fallback.", "warning");
    return;
  }

  await ctx.ui.custom<void>((tui, _theme, _keybindings, done) => {
    let mounted = true;
    let busy = true;
    let selectedIndex = 0;
    let memories: MemoryEntry[] = [];
    let page = 1;
    let pageSize = 20;
    let total = 0;
    let pinnedCount = 0;
    let statusLine = `Loading memories for ${workspaceId}…`;

    const clampSelection = () => {
      selectedIndex = Math.max(0, Math.min(selectedIndex, Math.max(0, memories.length - 1)));
    };

    const refresh = async (nextPage = page) => {
      busy = true;
      statusLine = `Refreshing memories for ${workspaceId}…`;
      tui.requestRender();
      try {
        const payload = await apiFetchJson<MemoryListResponse>(
          baseUrl,
          `/api/memory/items?workspaceId=${encodeURIComponent(workspaceId)}&limit=${pageSize}&page=${nextPage}`,
          { token },
        );
        if (!mounted) return;
        page = payload.page ?? nextPage;
        pageSize = payload.pageSize ?? pageSize;
        total = payload.total ?? 0;
        pinnedCount = payload.pinned ?? 0;
        memories = payload.items ?? [];
        clampSelection();
        statusLine = `Loaded ${memories.length} memories on page ${page} of ${Math.max(1, Math.ceil(Math.max(total, 0) / Math.max(pageSize, 1)))}.`;
      } catch (error) {
        if (!mounted) return;
        statusLine = `Failed to load memories: ${error instanceof Error ? error.message : String(error)}`;
        notify(ctx.ui, statusLine, "error");
      } finally {
        if (!mounted) return;
        busy = false;
        tui.requestRender();
      }
    };

    void refresh();

    return {
      render: (width) => renderMemoryBrowser(
        memories,
        selectedIndex,
        width,
        busy ? `${statusLine} (loading)` : statusLine,
        page,
        pageSize,
        total,
        pinnedCount,
      ),
      handleInput: (data) => {
        const key = normalizeKey(data);
        if (key === "q" || key === "escape" || key === "ctrl+c") {
          mounted = false;
          done();
          return;
        }
        if (key === "up" || key === "k") {
          selectedIndex = Math.max(0, selectedIndex - 1);
          tui.requestRender();
          return;
        }
        if (key === "down" || key === "j") {
          selectedIndex = Math.min(Math.max(0, memories.length - 1), selectedIndex + 1);
          tui.requestRender();
          return;
        }
        if (key === "left" || key === "h") {
          if (page > 1) {
            selectedIndex = 0;
            void refresh(page - 1);
          }
          return;
        }
        if (key === "right" || key === "l") {
          const totalPages = Math.max(1, Math.ceil(Math.max(total, 0) / Math.max(pageSize, 1)));
          if (page < totalPages) {
            selectedIndex = 0;
            void refresh(page + 1);
          }
          return;
        }
        if (key === "r") {
          void refresh();
        }
      },
      invalidate: () => {
        mounted = false;
      },
    };
  }, { overlay: true });
}

import {
  type ExtensionAPI,
  type ExtensionCommandContext,
  apiFetchJson,
  normalizeKey,
  notify,
  pad,
  timeAgo,
  truncate,
} from "./shared.js";

type DirectionLayer = {
  content?: string | null;
  source?: string;
  teamOverride?: string | null;
  preferredModel?: string | null;
  note?: string;
};

type DirectionAllResponse = {
  layers?: {
    l1?: DirectionLayer;
    l2?: DirectionLayer;
    l3?: DirectionLayer;
    l4?: DirectionLayer;
    l5?: DirectionLayer;
  };
  teamL1?: string | null;
  teamL2?: string | null;
};

type DirectionSynthesizeResponse = {
  synthesized?: string;
};

const TABS = ["l1", "l2", "l3", "l4", "l5", "synth"] as const;
type DirectionTab = (typeof TABS)[number];

function wrapLines(value: string, width: number, maxLines: number): string[] {
  const safeWidth = Math.max(8, width);
  const output: string[] = [];
  for (const rawLine of value.split(/\r?\n/)) {
    if (output.length >= maxLines) break;
    const line = rawLine || " ";
    let rest = line;
    while (rest.length > safeWidth && output.length < maxLines) {
      output.push(pad(rest.slice(0, safeWidth), safeWidth));
      rest = rest.slice(safeWidth);
    }
    if (output.length < maxLines) {
      output.push(pad(truncate(rest, safeWidth), safeWidth));
    }
  }
  return output.length > 0 ? output : [pad(" ", safeWidth)];
}

function summarizeLayer(tab: DirectionTab, data: DirectionAllResponse): string {
  if (tab === "synth") {
    return "Merged L1→L5 context preview";
  }
  const layer = data.layers?.[tab];
  if (!layer) {
    return "Layer unavailable";
  }
  const pieces: string[] = [];
  if (tab === "l1") {
    pieces.push(`source ${layer.source || "global"}`);
    if (data.teamL1) pieces.push("team override available");
  }
  if (tab === "l2" && data.teamL2) {
    pieces.push("team override available");
  }
  if (tab === "l3" && layer.preferredModel) {
    pieces.push(`model ${layer.preferredModel}`);
  }
  if ((tab === "l4" || tab === "l5") && layer.note) {
    pieces.push(layer.note);
  }
  if (!layer.content && layer.note) {
    pieces.push(layer.note);
  } else {
    pieces.push(layer.content ? `${layer.content.length} chars` : "empty");
  }
  return pieces.join(" • ");
}

function renderDirectionView(
  workspaceId: string,
  activeTab: DirectionTab,
  payload: DirectionAllResponse,
  synthesized: string,
  width: number,
  statusLine: string,
  loadedAt: string | null,
): string[] {
  const totalWidth = Math.max(88, width);
  const listWidth = Math.max(24, Math.floor(totalWidth * 0.26));
  const detailWidth = Math.max(56, totalWidth - listWidth - 3);
  const leftLines: string[] = [pad(`[DIRECTION • ${workspaceId}]`, listWidth)];

  for (const tab of TABS) {
    const marker = tab === activeTab ? "> " : "  ";
    const label = tab === "synth" ? "Synthesized" : tab.toUpperCase();
    leftLines.push(pad(truncate(`${marker}${label}`, listWidth), listWidth));
    leftLines.push(pad(truncate(`   ${summarizeLayer(tab, payload)}`, listWidth), listWidth));
  }

  const rightLines: string[] = [pad(`[${activeTab === "synth" ? "SYNTHESIZED" : activeTab.toUpperCase()}]`, detailWidth)];
  rightLines.push(pad(truncate(`Updated: ${timeAgo(loadedAt)}`, detailWidth), detailWidth));
  rightLines.push(" ".repeat(detailWidth));

  if (activeTab === "synth") {
    rightLines.push(...wrapLines(synthesized || "No synthesized direction available.", detailWidth, 18));
  } else {
    const layer = payload.layers?.[activeTab];
    if (layer?.preferredModel) {
      rightLines.push(pad(truncate(`Preferred model: ${layer.preferredModel}`, detailWidth), detailWidth));
    }
    if (layer?.source) {
      rightLines.push(pad(truncate(`Source: ${layer.source}`, detailWidth), detailWidth));
    }
    if (layer?.teamOverride) {
      rightLines.push(pad(truncate(`Team override present (${layer.teamOverride.length} chars)`, detailWidth), detailWidth));
    }
    if (layer?.note) {
      rightLines.push(pad(truncate(`Note: ${layer.note}`, detailWidth), detailWidth));
    }
    rightLines.push(...wrapLines(layer?.content || "No content saved for this layer.", detailWidth, 18 - Math.max(0, rightLines.length - 3)));
  }

  const height = Math.max(leftLines.length, rightLines.length);
  while (leftLines.length < height) leftLines.push(" ".repeat(listWidth));
  while (rightLines.length < height) rightLines.push(" ".repeat(detailWidth));

  const lines: string[] = [truncate(statusLine, totalWidth)];
  for (let i = 0; i < height; i += 1) {
    lines.push(`${leftLines[i]} │ ${rightLines[i]}`);
  }
  lines.push(" ");
  lines.push(truncate("↑/↓ move • 1/2/3/4/5/s jump • r refresh • e edit externally • q/esc close", totalWidth));
  return lines;
}

export async function openDirectionView(
  ctx: ExtensionCommandContext,
  _pi: ExtensionAPI,
  workspaceId: string,
  baseUrl: string,
  token?: string,
): Promise<void> {
  if (!ctx.ui.custom) {
    notify(ctx.ui, "Pi custom UI is unavailable in this session. Use /rorca-tui as fallback.", "warning");
    return;
  }

  await ctx.ui.custom<void>((tui, _theme, _keybindings, done) => {
    let mounted = true;
    let busy = true;
    let activeTabIndex = 0;
    let payload: DirectionAllResponse = {};
    let synthesized = "";
    let loadedAt: string | null = null;
    let statusLine = `Loading direction for ${workspaceId}…`;

    const setTab = (tab: DirectionTab) => {
      activeTabIndex = TABS.indexOf(tab);
      tui.requestRender();
    };

    const refresh = async () => {
      busy = true;
      statusLine = `Refreshing direction for ${workspaceId}…`;
      tui.requestRender();
      try {
        const [allLayers, synth] = await Promise.all([
          apiFetchJson<DirectionAllResponse>(baseUrl, `/api/direction/all?workspaceId=${encodeURIComponent(workspaceId)}`, { token }),
          apiFetchJson<DirectionSynthesizeResponse>(baseUrl, `/api/direction/synthesize`, {
            method: "POST",
            body: { workspaceId },
            token,
          }),
        ]);
        if (!mounted) return;
        payload = allLayers;
        synthesized = synth.synthesized ?? "";
        loadedAt = new Date().toISOString();
        statusLine = `Loaded direction for ${workspaceId}.`;
      } catch (error) {
        if (!mounted) return;
        statusLine = `Failed to load direction: ${error instanceof Error ? error.message : String(error)}`;
        notify(ctx.ui, statusLine, "error");
      } finally {
        if (!mounted) return;
        busy = false;
        tui.requestRender();
      }
    };

    void refresh();

    return {
      render: (width) => renderDirectionView(
        workspaceId,
        TABS[activeTabIndex]!,
        payload,
        synthesized,
        width,
        busy ? `${statusLine} (loading)` : statusLine,
        loadedAt,
      ),
      handleInput: (data) => {
        const key = normalizeKey(data);
        if (key === "q" || key === "escape" || key === "ctrl+c") {
          mounted = false;
          done();
          return;
        }
        if (key === "up" || key === "k") {
          activeTabIndex = Math.max(0, activeTabIndex - 1);
          tui.requestRender();
          return;
        }
        if (key === "down" || key === "j") {
          activeTabIndex = Math.min(TABS.length - 1, activeTabIndex + 1);
          tui.requestRender();
          return;
        }
        if (key === "1") return setTab("l1");
        if (key === "2") return setTab("l2");
        if (key === "3") return setTab("l3");
        if (key === "4") return setTab("l4");
        if (key === "5") return setTab("l5");
        if (key === "s") return setTab("synth");
        if (key === "r") {
          void refresh();
          return;
        }
        if (key === "e") {
          notify(ctx.ui, "Direction editing remains external for now. Use the dashboard settings or /rorca-tui to edit safely.", "info");
        }
      },
      invalidate: () => {
        mounted = false;
      },
    };
  }, { overlay: true });
}

import {
  type ExtensionAPI,
  type ExtensionCommandContext,
  type WorkspaceSummary,
  apiFetchJson,
  getWorkspaces,
  normalizeKey,
  notify,
  pad,
  timeAgo,
  truncate,
} from "./shared.js";

type WorkspaceHealth = {
  score?: number;
  semantic?: {
    graphAvailable?: boolean;
    vertices?: number;
    edges?: number;
    embeddings?: { total?: number };
    searchMode?: string;
  };
  trend?: Array<{ score?: number; timestamp?: string }>;
};

function renderWorkspaceView(
  workspaces: WorkspaceSummary[],
  selectedIndex: number,
  width: number,
  activeWorkspaceId: string,
  health: WorkspaceHealth | null,
  statusLine: string,
): string[] {
  const totalWidth = Math.max(84, width);
  const listWidth = Math.max(28, Math.floor(totalWidth * 0.35));
  const detailWidth = Math.max(44, totalWidth - listWidth - 3);
  const selected = workspaces[selectedIndex];

  const leftLines: string[] = [pad(`[WORKSPACES • ${workspaces.length}]`, listWidth)];
  if (workspaces.length === 0) {
    leftLines.push(pad("No workspaces registered.", listWidth));
  } else {
    workspaces.forEach((workspace, index) => {
      const isSelected = index === selectedIndex;
      const isActive = workspace.id === activeWorkspaceId;
      const marker = isSelected ? "> " : "  ";
      const prefix = isActive ? "●" : "○";
      leftLines.push(pad(truncate(`${marker}${prefix} ${workspace.label}`, listWidth), listWidth));
      leftLines.push(pad(truncate(`   ${workspace.id}`, listWidth), listWidth));
    });
  }

  const rightLines: string[] = [pad("[DETAIL]", detailWidth)];
  if (!selected) {
    rightLines.push(pad("Select a workspace.", detailWidth));
  } else {
    rightLines.push(pad(truncate(`Label: ${selected.label}`, detailWidth), detailWidth));
    rightLines.push(pad(truncate(`Id: ${selected.id}`, detailWidth), detailWidth));
    rightLines.push(pad(truncate(`Path: ${selected.path}`, detailWidth), detailWidth));
    rightLines.push(pad(truncate(`Domains: ${(selected.domains ?? []).join(", ") || "none"}`, detailWidth), detailWidth));
    rightLines.push(" ".repeat(detailWidth));
    rightLines.push(pad(truncate(`Health score: ${health?.score ?? "unknown"}`, detailWidth), detailWidth));
    rightLines.push(
      pad(
        truncate(
          `Semantic: ${health?.semantic?.searchMode ?? "unknown"} • graph ${health?.semantic?.graphAvailable ? "on" : "off"} • embeddings ${health?.semantic?.embeddings?.total ?? 0}`,
          detailWidth,
        ),
        detailWidth,
      ),
    );
    const trend = health?.trend?.[health.trend.length - 1];
    rightLines.push(pad(truncate(`Last health sample: ${timeAgo(trend?.timestamp ?? null)}`, detailWidth), detailWidth));
  }

  const height = Math.max(leftLines.length, rightLines.length);
  while (leftLines.length < height) leftLines.push(" ".repeat(listWidth));
  while (rightLines.length < height) rightLines.push(" ".repeat(detailWidth));

  const lines: string[] = [truncate(statusLine, totalWidth)];
  for (let index = 0; index < height; index += 1) {
    lines.push(`${leftLines[index]} │ ${rightLines[index]}`);
  }
  lines.push(" ");
  lines.push(truncate("↑/↓ move • enter switch • r refresh • q/esc close", totalWidth));
  return lines;
}

export async function openWorkspaceView(
  ctx: ExtensionCommandContext,
  _pi: ExtensionAPI,
  activeWorkspaceId: string,
  onSwitch: (workspace: WorkspaceSummary) => void,
  baseUrl: string,
  token?: string,
): Promise<void> {
  if (!ctx.ui.custom) {
    notify(ctx.ui, "Pi custom UI is unavailable in this session. Use /rorca-tui as fallback.", "warning");
    return;
  }

  await ctx.ui.custom<void>((tui, _theme, _keybindings, done) => {
    let mounted = true;
    let busy = true;
    let selectedIndex = 0;
    let workspaces: WorkspaceSummary[] = [];
    let selectedWorkspaceId = activeWorkspaceId;
    let healthByWorkspace = new Map<string, WorkspaceHealth | null>();
    let statusLine = `Loading workspaces…`;

    const clampSelection = () => {
      selectedIndex = Math.max(0, Math.min(selectedIndex, Math.max(0, workspaces.length - 1)));
    };

    const loadHealth = async (workspaceId: string) => {
      if (healthByWorkspace.has(workspaceId)) {
        return;
      }
      try {
        const health = await apiFetchJson<WorkspaceHealth>(
          baseUrl,
          `/api/workspaces/${encodeURIComponent(workspaceId)}/health`,
          { token },
        );
        if (!mounted) return;
        healthByWorkspace.set(workspaceId, health);
        tui.requestRender();
      } catch {
        if (!mounted) return;
        healthByWorkspace.set(workspaceId, null);
        tui.requestRender();
      }
    };

    const refresh = async () => {
      busy = true;
      statusLine = "Refreshing workspaces…";
      healthByWorkspace = new Map<string, WorkspaceHealth | null>();
      tui.requestRender();
      try {
        workspaces = await getWorkspaces(baseUrl, token);
        const activeIndex = workspaces.findIndex((workspace) => workspace.id === selectedWorkspaceId);
        selectedIndex = activeIndex >= 0 ? activeIndex : 0;
        clampSelection();
        statusLine = `Loaded ${workspaces.length} workspaces.`;
        const selected = workspaces[selectedIndex];
        if (selected) {
          void loadHealth(selected.id);
        }
      } catch (error) {
        statusLine = `Failed to load workspaces: ${error instanceof Error ? error.message : String(error)}`;
        notify(ctx.ui, statusLine, "error");
      } finally {
        busy = false;
        tui.requestRender();
      }
    };

    void refresh();

    return {
      render: (width) => {
        const selected = workspaces[selectedIndex];
        return renderWorkspaceView(
          workspaces,
          selectedIndex,
          width,
          selectedWorkspaceId,
          selected ? (healthByWorkspace.get(selected.id) ?? null) : null,
          busy ? `${statusLine} (loading)` : statusLine,
        );
      },
      handleInput: (data) => {
        const key = normalizeKey(data);
        if (key === "q" || key === "escape" || key === "ctrl+c") {
          mounted = false;
          done();
          return;
        }
        if (key === "up" || key === "k") {
          selectedIndex = Math.max(0, selectedIndex - 1);
          const selected = workspaces[selectedIndex];
          if (selected) void loadHealth(selected.id);
          tui.requestRender();
          return;
        }
        if (key === "down" || key === "j") {
          selectedIndex = Math.min(Math.max(0, workspaces.length - 1), selectedIndex + 1);
          const selected = workspaces[selectedIndex];
          if (selected) void loadHealth(selected.id);
          tui.requestRender();
          return;
        }
        if (key === "r") {
          void refresh();
          return;
        }
        if (key === "enter") {
          const selected = workspaces[selectedIndex];
          if (!selected) {
            return;
          }
          selectedWorkspaceId = selected.id;
          onSwitch(selected);
          notify(ctx.ui, `Active Rorca workspace: ${selected.label}`, "success");
          mounted = false;
          done();
        }
      },
      invalidate: () => {
        mounted = false;
      },
    };
  }, { overlay: true });
}

